    // when SSOT doesn't exist yet.
    let ssot_hash = if ssot_skill_md.exists() {
        hash::compute_core_hash(&ssot_skill_md).ok()
    } else {
        None
    };

    let mut updates = Vec::new();

    // Check all active installation paths (scoped to project) against SSOT
