                            skill_id,
                            skill_name: skill.name.clone(),
                            source_path: scanner::normalize_path(&skill_dir),
                            old_hash,
                            new_hash: install_hash,
                            changed_tool: Some(tool_name),
                            changed_tool_id: Some(*tool_id),
                        });
                    }
                }
            }
        }
